package com.brawlville.game;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.view.*;import android.webkit.*;import java.io.*;import java.net.*;import java.security.*;import org.json.*;import java.util.concurrent.*;import java.util.*;
public class MainActivity extends Activity {
 private static final String HOST="appassets.androidplatform.net",HOME="https://appassets.androidplatform.net/game/index.html";
 private final Handler updateHandler=new Handler(Looper.getMainLooper());private long deferredVersion=0,deferredUntil=0;
 private final Runnable updatePoll=new Runnable(){public void run(){checkUpdates(false);updateHandler.postDelayed(this,120000);}};
 private long lastUpdateCheck=0;private boolean updateChecking=false,updateDialog=false,pendingInstall=false;private final ExecutorService updater=Executors.newSingleThreadExecutor();
 private WebView web;private PermissionRequest mic;private ValueCallback<Uri[]> chooser;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);web=new WebView(this);setContentView(web);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setDatabaseEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMediaPlaybackRequiresUserGesture(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSupportMultipleWindows(false);settings.setBuiltInZoomControls(false);settings.setUseWideViewPort(true);settings.setLoadWithOverviewMode(true);android.webkit.CookieManager.getInstance().setAcceptCookie(true);
 web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest req){Uri url=req.getUrl();if(!HOST.equals(url.getHost())||!"https".equals(url.getScheme()))return null;try{String path=url.getPath();if(path==null||!path.startsWith("/game/")||path.contains(".."))throw new IOException();String file=path.substring(1),mime=URLConnection.guessContentTypeFromName(file);if(file.endsWith(".js"))mime="application/javascript";else if(file.endsWith(".css"))mime="text/css";else if(file.endsWith(".svg"))mime="image/svg+xml";else if(file.endsWith(".wasm"))mime="application/wasm";else if(file.endsWith(".json"))mime="application/json";if(mime==null)mime="application/octet-stream";return new WebResourceResponse(mime,mime.startsWith("text/")||mime.contains("javascript")||mime.contains("json")?"UTF-8":null,getAssets().open(file));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",Collections.emptyMap(),new ByteArrayInputStream("Fichier introuvable".getBytes()));}}
 @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){Uri url=req.getUrl();if("https".equals(url.getScheme())&&HOST.equals(url.getHost()))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,url));}catch(Exception ignored){}return true;}
 @Override public void onPageFinished(WebView view,String url){immersive();}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!"https".equals(request.getOrigin().getScheme())||!HOST.equals(request.getOrigin().getHost())||!Arrays.asList(request.getResources()).contains(PermissionRequest.RESOURCE_AUDIO_CAPTURE)){request.deny();return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED){request.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});}else{if(mic!=null)mic.deny();mic=request;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},30);}});}
 @Override public void onPermissionRequestCanceled(PermissionRequest request){if(mic==request)mic=null;}
 @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;try{startActivityForResult(params.createIntent(),31);}catch(Exception e){chooser=null;callback.onReceiveValue(null);}return true;}
 @Override public boolean onConsoleMessage(ConsoleMessage message){android.util.Log.d("BrawlWeb",message.message()+" @ "+message.sourceId()+":"+message.lineNumber());return true;}});
 long previous=getPreferences(MODE_PRIVATE).getLong("assetsVersion",0);if(previous!=installedVersion()){web.clearCache(true);getPreferences(MODE_PRIVATE).edit().putLong("assetsVersion",installedVersion()).apply();}web.addJavascriptInterface(new NativeBridge(),"BrawlAndroid");web.loadUrl(HOME);immersive();checkUpdates(false);}
 private void immersive(){getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)immersive();}
 @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grants){super.onRequestPermissionsResult(requestCode,permissions,grants);if(requestCode==30&&mic!=null){if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)mic.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else mic.deny();mic=null;}}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==31&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(resultCode,data));chooser=null;}}
 @Override public void onBackPressed(){web.evaluateJavascript("(()=>{const d=document.getElementById('modal');if(d?.open){d.close();return true;}return false;})()",value->{if(!"true".equals(value)){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setMessage("Quitter Brawl Ville ?").setPositiveButton("Quitter",(d,w)->finish()).setNegativeButton("Rester",null).show();}});}
 @Override protected void onPause(){super.onPause();updateHandler.removeCallbacks(updatePoll);web.onPause();}
 @Override protected void onResume(){super.onResume();updateHandler.removeCallbacks(updatePoll);updateHandler.postDelayed(updatePoll,120000);if(web!=null)web.onResume();if(pendingInstall&&getPackageManager().canRequestPackageInstalls()){pendingInstall=false;installUpdate();}else checkUpdates(false);}
 @Override protected void onDestroy(){updateHandler.removeCallbacks(updatePoll);if(mic!=null)mic.deny();if(web!=null){web.stopLoading();web.destroy();}updater.shutdownNow();super.onDestroy();}
 public class NativeBridge {@JavascriptInterface public void checkForUpdates(){runOnUiThread(()->checkUpdates(true));}@JavascriptInterface public int versionCode(){return (int)installedVersion();}}
 private long installedVersion(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionCode;}catch(Exception e){return 0;}}
 private String readUrl(String address,int maximum)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Cache-Control","no-cache");try{if(c.getResponseCode()!=200)throw new IOException("Serveur indisponible");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>maximum)throw new IOException("Réponse trop grande");out.write(b,0,n);}return out.toString("UTF-8");}}finally{c.disconnect();}}
 private void message(String text){runOnUiThread(()->android.widget.Toast.makeText(this,text,android.widget.Toast.LENGTH_LONG).show());}
 private void checkUpdates(boolean manual){if(web==null||isFinishing()||updateChecking||updateDialog||!manual&&System.currentTimeMillis()-lastUpdateCheck<60000)return;lastUpdateCheck=System.currentTimeMillis();updateChecking=true;updater.execute(()->{try{JSONObject location=new JSONObject(readUrl("https://raw.githubusercontent.com/tommyaudetcontact-wq/HubParents/main/server-location.json?t="+System.currentTimeMillis(),65536));String origin=location.optString("origin");if(!location.optBoolean("online")||!origin.matches("https://[a-z0-9-]+\\.trycloudflare\\.com"))throw new IOException("Le serveur sur le PC est éteint");JSONObject release=new JSONObject(readUrl(origin+"/app/version?t="+System.currentTimeMillis(),65536));long version=release.getLong("versionCode");if(!getPackageName().equals(release.getString("applicationId")))throw new IOException("Version incompatible");if(!manual&&version==deferredVersion&&System.currentTimeMillis()<deferredUntil)return;if(version>installedVersion()){runOnUiThread(()->{if(isFinishing())return;updateDialog=true;AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle("Brawl Ville · mise à jour").setMessage("La version "+release.optString("versionName")+" est disponible. Télécharger et installer ?").setPositiveButton("Mettre à jour",(d,w)->{updateDialog=false;downloadUpdate(origin,release);});if(release.optLong("minimumVersionCode",1)>installedVersion())dialog.setNegativeButton("Quitter",(d,w)->finish()).setCancelable(false);else dialog.setNegativeButton("Plus tard",(d,w)->{deferredVersion=version;deferredUntil=System.currentTimeMillis()+1800000;updateDialog=false;}).setOnCancelListener(d->{deferredVersion=version;deferredUntil=System.currentTimeMillis()+1800000;updateDialog=false;});dialog.show();});}else if(manual)message("Le jeu est à jour.");}catch(Exception e){if(manual)message("Vérification impossible : "+e.getMessage());}finally{updateChecking=false;}});}
 private void downloadUpdate(String origin,JSONObject release){message("Téléchargement de la mise à jour…");updater.execute(()->{File temp=new File(getCacheDir(),"update.part"),apk=new File(getCacheDir(),"update.apk");try{String expected=release.getString("sha256");long expectedSize=release.getLong("size");if(!expected.matches("[a-f0-9]{64}")||expectedSize<1000||expectedSize>250000000||!"/app/apk".equals(release.getString("apkPath")))throw new IOException("Métadonnées invalides");HttpURLConnection connection=(HttpURLConnection)new URL(origin+"/app/apk").openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setInstanceFollowRedirects(false);MessageDigest hash=MessageDigest.getInstance("SHA-256");long total=0;try{if(connection.getResponseCode()!=200)throw new IOException("APK indisponible");try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(temp)){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1){total+=n;if(total>expectedSize)throw new IOException("Taille invalide");out.write(bytes,0,n);hash.update(bytes,0,n);}}}finally{connection.disconnect();}StringBuilder digest=new StringBuilder();for(byte v:hash.digest())digest.append(String.format(java.util.Locale.ROOT,"%02x",v&255));if(total!=expectedSize||!expected.equals(digest.toString()))throw new IOException("Vérification du téléchargement échouée");android.content.pm.PackageInfo archive=getPackageManager().getPackageArchiveInfo(temp.getAbsolutePath(),PackageManager.GET_SIGNATURES),own=getPackageManager().getPackageInfo(getPackageName(),PackageManager.GET_SIGNATURES);if(archive==null||!getPackageName().equals(archive.packageName)||archive.versionCode!=release.getLong("versionCode")||archive.signatures==null||own.signatures==null||!java.util.Arrays.equals(archive.signatures,own.signatures))throw new IOException("La signature de la mise à jour ne correspond pas au jeu");if(apk.exists()&&!apk.delete())throw new IOException("Ancienne mise à jour occupée");if(!temp.renameTo(apk))throw new IOException("Impossible de préparer la mise à jour");runOnUiThread(()->{if(!getPackageManager().canRequestPackageInstalls()){pendingInstall=true;new AlertDialog.Builder(this).setTitle("Autoriser la mise à jour").setMessage("Android demande d’autoriser Brawl Ville à installer ses mises à jour. Active cette permission puis reviens au jeu.").setPositiveButton("Ouvrir les réglages",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())))).setNegativeButton("Annuler",(d,w)->pendingInstall=false).show();}else installUpdate();});}catch(Exception e){temp.delete();message("Mise à jour impossible : "+e.getMessage());}});}
 private void installUpdate(){try{Uri uri=Uri.parse("content://"+getPackageName()+".updates/update.apk");Intent install=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(install);}catch(Exception e){message("Ouvre le fichier APK pour terminer l’installation.");}}

}
